      "check_id": "CKV_AWS_3",
      "title": "EBS volume encryption not enabled",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "HIGH",
      "explanation": "The EBS volume is not encrypted, which means data stored on the volume is not protected at rest. This can lead to unauthorized access to sensitive data if the volume is compromised."
    }
  ],
  "patched_code": "resource \"aws_ebs_volume\" \"changeme_simple_aws_ebs_volume\" {\n  availability_zone = data.aws_availability_zones.changeme_available_az_list.names[0]\n  size              = 10\n  type              = \"standard\"\n  encrypted         = true\n}",
  "fix_summary": "Enabled encryption for the EBS volume by setting the 'encrypted' attribute to 'true'."
}
